text:
{
  "tasks": [
    {
      "task_id": "T1",
      "title": "已解决工单优先级数量分布及前两名",
      "business_question": "统计状态为“已解决”的工单中，各优先级的工单数量是多少？并按数量降序排列取前两名。",
      "priority": "P0",
      "priority_reason": "核心需求：直接回答用户关于已解决工单按优先级统计并取前两名的业务问题。删除此任务将无法完成主要分析目标。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已解决"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "ticket_count"
              }
            ],
            "dimensions": [
              "field_0004"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "ticket_count",
            "direction": "desc"
          }
        },
        {
          "step_id": "S4",
          "operation": "top_n",
          "params": {
            "field": "ticket_count",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
}
